#include <bits/stdc++.h>
using namespace std;

void solveProblem(istream& in, ostream& out) {
    int n;
    in >> n;
    string sLine;
    in >> sLine;
    vector<char> s(sLine.begin(), sLine.end());
    vector<int> beauty(n);
    int totalBeauty = 0;
    for (int i = 0; i < n; i++) {
        in >> beauty[i];
        totalBeauty += beauty[i];
    }

    vector<int> sameCharPairs;
    vector<int> countChars(128, 0);
    char maxCharInPairs = 'a';

    for (int i = 0; i < n / 2; i++) {
        if (s[i] == s[n - 1 - i]) {
            sameCharPairs.push_back(i);
            if (++countChars[s[i]] > countChars[maxCharInPairs]) {
                maxCharInPairs = s[i];
            }
        }
    }

    int answer = totalBeauty;
    for (int idx : sameCharPairs) {
        answer -= min(beauty[idx], beauty[n - 1 - idx]);
    }

    if (countChars[maxCharInPairs] > (int)sameCharPairs.size() / 2) {
        vector<int> penalties;
        for (int i = 0; i < n / 2; i++) {
            if (s[i] != s[n - 1 - i] && s[i] != maxCharInPairs && s[n - 1 - i] != maxCharInPairs) {
                penalties.push_back(min(beauty[i], beauty[n - 1 - i]));
            }
        }
        sort(penalties.begin(), penalties.end());
        int rem = 2 * countChars[maxCharInPairs] - (int)sameCharPairs.size();
        for (int i = 0; i < rem; i++) {
            answer -= penalties[i];
        }
    }

    out << answer << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solveProblem(cin, cout);
    return 0;
}

